) ? &absinfo : NULL);     }      struct libevdev_uinput *ui;     if (libevdev_uinput_create_from_device(device, LIBEVDEV_UINPUT_OPEN_MANAGED, &ui) < 0) {         fprintf(stderr, "Failed to create uinput device
");         exit(EXIT_FAILURE);     }      libevdev_free(device);     return ui; }  static void udp_server(void) {     int sockfd;     struct sockaddr_in serv_addr, cli_addr;     socklen_t cli_len = sizeof(cli_addr);     char buffer[BUFFER_SIZE];      sockfd = socket(AF_INET, SOCK_DGRAM, 0);     if (sockfd < 0) {         perror("ERROR opening socket");         exit(1);     }      memset(&serv_addr, 0, sizeof(serv_addr));     serv_addr.sin_family = AF_INET;     serv_addr.sin_addr.s_addr = INADDR_ANY;     serv_addr.sin_port = htons(PORT);      if (bind(sockfd, (struct sockaddr *) &serv_addr, sizeof(serv_addr)) < 0) {         perror("ERROR on binding");         exit(1);     }      while (1) {         int n = recvfrom(sockfd, buffer, BUFFER_SIZE, 0, (struct sockaddr *) &cli_addr, &cli_len);         if (n < 0) {             perror("ERROR in recvfrom");         } else {             int event_index, event_value;             memcpy(&event_index, buffer, sizeof(int));             memcpy(&event_value, buffer + sizeof(int), sizeof(int));              if (event_index >= 0 && event_index < sizeof(REGISTERED_EVENTS) / sizeof(REGISTERED_EVENTS[0])) {                 libevdev_uinput_write_event(controller, REGISTERED_EVENTS[event_index].type,                                             REGISTERED_EVENTS[event_index].code, event_value);                 libevdev_uinput_write_event(controller, EV_SYN, SYN_REPORT, 0);             }         }     }      close(sockfd); }  int main() {     controller = controller_create();     udp_server();     libevdev_uinput_destroy(controller);     return 0; } ``` Here is client code: ```zig const std = @import("std"); const rl = @import("raylib"); const net = std.net; const posix = std.posix; const mem = std.mem;  // Define your controller event indices based on the JSON mapping const ControllerEvents = enum(i16) {     ANALOG_LX = 0,     ANALOG_LY = 1,     ANALOG_RX = 2,     ANALOG_RY = 3,     L1 = 4,     L2 = 5,     R1 = 6,     R2 = 7,     TRIANGLE = 8,     CROSS = 9,     SQUARE = 10,     CIRCLE = 11,     UP = 12,     DOWN = 13,     LEFT = 14,     RIGHT = 15,     SELECT = 16,     START = 17, };  // Define a function to send the entire controller state fn sendControllerState(sock: posix.fd_t, addr: *const net.Address, controllerState: []const i16) !void {     const sockaddr = &addr.any;     const addrlen = addr.getOsSockLen();     const bytesToSend = mem.asBytes(controllerState[0..@intFromEnum(ControllerEvents.START)+1]); // Ensure the entire array is converted to bytes     const totalBytes = bytesToSend.len; // Calculate the total number of bytes to send      const ret = try posix.sendto(sock, bytesToSend, 0, sockaddr, addrlen);     std.debug.print("sent {x}
", .{bytesToSend});     if (ret != totalBytes) {         std.log.warn("Warning: Not all data was sent. Expected to send {}, but sent {}
", .{ totalBytes, ret });     } }  // Create a UDP server and return the socket and bound address fn createUDPServer() !struct {     sock: posix.fd_t,     addr: net.Address, } {     const sock = try posix.socket(posix.AF.INET, posix.SOCK.DGRAM, 0);     const addr = try net.Address.parseIp4("127.0.0.1", 31415);     try posix.bind(sock, &addr.any, addr.getOsSockLen());     return .{ .sock = sock, .addr = addr }; }  // Initialize controller state fn initializeControllerState() [@intFromEnum(ControllerEvents.START)+1]i16 {     var controllerState: [@intFromEnum(ControllerEvents.START)+1]i16 = undefined;     @memset(controllerState[0..], 0); // Set all values to 0     return controllerState; }  pub fn main() anyerror!void {     const alloc = std.heap.page_allocator;     _ = alloc;      // Initialization     //--------------------------------------------------------------------------------------     const screenWidth = 800;     const screenHeight = 450;      rl.initWindow(screenWidth, screenHeight, "raylib-zig example - keyboard to controller input");     defer rl.closeWindow(); // Close window and OpenGL context      rl.setTargetFPS(60); // Set our game to run at 60 frames-per-second     //--------------------------------------------------------------------------------------      // Initialize controller state     var controllerState = initializeControllerState();      // Create a UDP socket for sending packets     const sock = try posix.socket(posix.AF.INET, posix.SOCK.DGRAM, 0);      defer posix.close(sock); // Close the socket when done      // Main game loop     while (!rl.windowShouldClose()) { // Detect window close button or ESC key         // Update         //----------------------------------------------------------------------------------         // Update controller state based on keyboard input         controllerState[@intFromEnum(ControllerEvents.UP)] = if (rl.isKeyDown(rl.KeyboardKey.key_up)) 1 else 0;         controllerState[@intFromEnum(ControllerEvents.DOWN)] = if (rl.isKeyDown(rl.KeyboardKey.key_down)) 1 else 0;         controllerState[@intFromEnum(ControllerEvents.LEFT)] = if (rl.isKeyDown(rl.KeyboardKey.key_left)) 1 else 0;         controllerState[@intFromEnum(ControllerEvents.RIGHT)] = if (rl.isKeyDown(rl.KeyboardKey.key_right)) 1 else 0;          // Send the current state of the controller to the server         const addr = try net.Address.parseIp4("127.0.0.1", 31415);         try sendControllerState(sock, &addr, &controllerState);           // Draw         //----------------------------------------------------------------------------------         rl.beginDrawing();         rl.clearBackground(rl.Color.white);         rl.drawText("Press arrow keys to simulate controller input!", 190, 200, 20, rl.Color.light_gray);         rl.endDrawing();         //----------------------------------------------------------------------------------     } } ``` Here is example Zig array that contains valid data: ``` // Simulated values for each event var eventCodesValues = [_][2]i16{     .{0, 32767},  // ANALOG_LX (full right)     .{1, 0},      // ANALOG_LY (center)     .{2, -32768}, // ANALOG_RX (full left)     .{3, 0},      // ANALOG_RY (center)     .{4, 1},      // L1 (pressed)     .{5, 0},      // L2 (released)     .{6, 1},      // R1 (pressed)     .{7, 0},      // R2 (released)     .{8, 1},      // TRIANGLE (pressed)     .{9, 0},      // CROSS (released)     .{10, 1},     // SQUARE (pressed)     .{11, 0},     // CIRCLE (released)     .{12, 1},     // UP (pressed)     .{13, 0},     // DOWN (released)     .{14, 1},     // LEFT (pressed)     .{15, 0},     // RIGHT (released)     .{16, 1},     // SELECT (pressed)     .{17, 0}      // START (released) }; ``` Modify client and server to use the same binary data format.

